<?php
session_start();include('check-login.php');include('dbstring.php');include_once('user-management-utils.php');include_once('department-result-workflow-utils.php');
drw_ensure_tables($con);$uid=isset($_SESSION['USERID'])?$_SESSION['USERID']:'';$isAdmin=drw_is_admin();$isAcademic=drw_is_academic_lead();$hods=drw_departments_for_hod($con,$uid);$isHod=!empty($hods);$msg='';
function dra($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
if(isset($_POST['workflow_action'])){$id=trim((string)$_POST['assignmentid']);$year=trim((string)$_POST['academicyear']);$action=trim((string)$_POST['workflow_action']);$note=trim((string)$_POST['note']);$assignment=mysqli_query($con,"SELECT sa.*,ds.departmentid FROM tblsubjectassignment sa INNER JOIN tbldepartmentsubject ds ON ds.classificationid=sa.classificationid WHERE sa.assignmentid='".mysqli_real_escape_string($con,$id)."' LIMIT 1");$a=$assignment?mysqli_fetch_assoc($assignment):null;$allowed=false;$status='';if($a){if($action==='submit'&&$a['userid']===$uid){$allowed=true;$status='submitted';}elseif(($action==='hod_approve'||$action==='return')&&$isHod){foreach($hods as $d)if($d['departmentid']===$a['departmentid'])$allowed=true;$status=$action==='hod_approve'?'hod_approved':'returned';}elseif(($action==='academic_approve'||$action==='return_academic')&&$isAcademic){$allowed=true;$status=$action==='academic_approve'?'academic_approved':'returned';}}if($allowed&&drw_update_status($con,$id,$year,$status,$uid,$note))$msg='Workflow updated successfully.';else $msg='This workflow action is not allowed.';}
$rows=array();$base="SELECT sa.assignmentid,sa.userid,sa.classid,sa.batchid,sa.termname,YEAR(sa.datetimeentry) academicyear,sub.subject,ce.class_name,b.batch,d.departmentid,d.departmentname,CONCAT_WS(' ',u.firstname,u.othernames,u.surname) teacher_name,COALESCE(w.status,'draft') workflow_status,COALESCE(w.lastnote,'') lastnote FROM tblsubjectassignment sa INNER JOIN tbldepartmentsubject ds ON ds.classificationid=sa.classificationid INNER JOIN tbldepartment d ON d.departmentid=ds.departmentid AND d.status='active' INNER JOIN tblsubjectclassification sc ON sc.classificationid=sa.classificationid INNER JOIN tblsubject sub ON sub.subjectid=sc.subjectid LEFT JOIN tblclassentry ce ON ce.class_entryid=sa.classid LEFT JOIN tblbatch b ON b.batchid=sa.batchid LEFT JOIN tblsystemuser u ON u.userid=sa.userid LEFT JOIN tbldepartmentresultworkflow w ON w.assignmentid=sa.assignmentid AND w.academicyear=YEAR(sa.datetimeentry) WHERE sa.status='active'";
if(!$isAdmin&&!$isAcademic&&!$isHod)$base.=" AND sa.userid='".mysqli_real_escape_string($con,$uid)."'";elseif($isHod&&!$isAcademic&&!$isAdmin){$ids=array();foreach($hods as $d)$ids[]="'".mysqli_real_escape_string($con,$d['departmentid'])."'";$base.=" AND d.departmentid IN (".implode(',',$ids).")";}elseif($isAcademic)$base.=" AND COALESCE(w.status,'draft') IN ('hod_approved','academic_approved','returned')";$r=mysqli_query($con,$base." ORDER BY d.departmentname,b.batch DESC,sa.termname DESC,sub.subject");if($r)while($x=mysqli_fetch_assoc($r))$rows[]=$x;
$role=$isAdmin?'Administrator':($isAcademic?'Assistant Head Academics':($isHod?'Head of Department':'Teacher'));
?>
<!doctype html><html><head><?php include('links.php');?><title>Department Result Approval</title><style>body{background:#f4f8fb;font-family:Arial;color:#17314b}.dra{max-width:1200px;margin:25px auto;background:#fff;padding:24px;border-radius:16px}.dra table{width:100%;border-collapse:collapse}.dra th,.dra td{padding:10px;border-bottom:1px solid #dce6ee;text-align:left;font-size:14px}.dra form{display:flex;gap:6px;flex-wrap:wrap}.dra input{padding:8px;color:#102a43;background:#fff;border:1px solid #9db2c5;border-radius:6px}.dra button{background:#087443;color:#fff;border:0;border-radius:6px;padding:8px 10px}.s{padding:4px 7px;border-radius:20px;background:#eef2f7;font-weight:bold;font-size:12px}@media(max-width:760px){.dra{margin:8px;padding:12px}.dra table{min-width:1050px}.scroll{overflow:auto}}</style></head><body><main class="dra"><h1>Department Result Approval</h1><p>Signed in as <strong><?php echo dra($role);?></strong>. Teacher → HOD → Assistant Head Academics → Administrator release.</p><?php if($msg!=='')echo '<p>'.dra($msg).'</p>';?><div class="scroll"><table><tr><th>Department / Subject</th><th>Teacher</th><th>Class Scope</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r){?><tr><td><strong><?php echo dra($r['departmentname']);?></strong><br><?php echo dra($r['subject']);?></td><td><?php echo dra($r['teacher_name']);?></td><td><?php echo dra($r['class_name'].' · '.$r['batch'].' · Sem '.$r['termname'].' · '.$r['academicyear']);?></td><td><span class="s"><?php echo dra(ucwords(str_replace('_',' ',$r['workflow_status'])));?></span><br><small><?php echo dra($r['lastnote']);?></small></td><td><form method="post"><input type="hidden" name="assignmentid" value="<?php echo dra($r['assignmentid']);?>"><input type="hidden" name="academicyear" value="<?php echo dra($r['academicyear']);?>"><input name="note" placeholder="Comment (optional)"><?php if($r['userid']===$uid&&in_array($r['workflow_status'],array('draft','returned'),true)){?><button name="workflow_action" value="submit">Submit to HOD</button><?php }?><?php if($isHod&&$r['workflow_status']==='submitted'){?><button name="workflow_action" value="hod_approve">Approve for Academic</button><button name="workflow_action" value="return">Return</button><?php }?><?php if($isAcademic&&$r['workflow_status']==='hod_approved'){?><button name="workflow_action" value="academic_approve">Final Academic Approval</button><button name="workflow_action" value="return_academic">Return</button><?php }?></form></td></tr><?php }?></table></div></main></body></html>
